{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the expected image.",
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.VideoInputSchema",
  "description": "Schema for a video input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.VideoInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the expected video.",
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.VideoUrl",
  "description": "A video URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the video.",
      "type": "string"
    }
  },
  "required": [
    "url"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.IntegerInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the integer.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "oneOf": [
    {
      "description": "Returns the params input as-is.",
      "type": "string",
      "const": "input"
    },
    {
      "description": "Returns the params output as-is.",
      "type": "string",
      "const": "output"
    },
    {
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "const": "task_output_l1_normalized"
    },
    {
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "const": "task_output_weighted_sum"
    },
    {
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "const": "input_items_output_length"
    },
    {
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "const": "input_items_optional_context_split"
    },
    {
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "const": "input_items_optional_context_merge"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    },
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "url"
  ]
}
